function parseArrayBuffer(buffer) {
  // Check if the first 4 bytes match the magic/signature
  if (buffer[0] !== "M" || buffer[1] !== "A" || buffer[2] !== "G" || buffer[3] !== "I") {
    return { error: "Invalid magic/signature" };
  }

  // Read the file version
  const fileVersion = buffer.readInt32LE(4);

  // Read the data size
  const dataSize = buffer.readInt32LE(8);

  // Check if the data size is within bounds
  if (dataSize > buffer.byteLength - 12) {
    return { error: "Data size is too large" };
  }

  // Read the data
  const data = new TextDecoder("utf-8").decode(new Uint8Array(buffer.slice(12, 12 + dataSize)));

  // Try to parse the data as JSON
  try {
    return { parsed_object: JSON.parse(data) };
  } catch (error) {
    return { error: "Data could not be parsed as JSON" };
  }
}
